# 45 venture capital firms: (slug, name, url, verified fact, observation 1, observation 2, slide notes [(text, fx, fy)])
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
("sequoia-capital","Sequoia Capital","https://www.sequoiacap.com/","Don Valentine founded Sequoia Capital in Menlo Park, California, in 1972.","Spaced, heavy capitals sit next to a small green mark inspired by the sequoia tree.","Naming the firm after a tree that grows for thousands of years is a statement about long-term thinking."),
("andreessen-horowitz","Andreessen Horowitz","https://a16z.com/","Marc Andreessen and Ben Horowitz founded the firm in 2009.","Two tall stacked surnames turn a long name into a block of type.","The firm is better known as a16z, short for the 16 letters between the a and the z."),
("accel","Accel","https://www.accel.com/","Arthur Patterson and Jim Swartz founded Accel in Palo Alto in 1983.","A heavy, high-contrast serif makes a short name look bold and editorial.","The name is a shortened form of accelerate, which suits a firm that funds fast-growing companies."),
("benchmark","Benchmark","https://www.benchmark.com/","Benchmark was founded in 1995 and is known for backing eBay, Uber and Twitter early.","Very widely spaced capitals sit inside a thin box.","The quiet logo suits a small partnership that avoids publicity."),
("kleiner-perkins","Kleiner Perkins","https://www.kleinerperkins.com/","Eugene Kleiner and Tom Perkins founded the firm in Menlo Park in 1972.","A small geometric icon sits next to widely spaced capitals.","The two founders' names became one of the most famous brands in Silicon Valley."),
("greylock","Greylock","https://greylock.com/","Greylock was founded in Boston in 1965, making it one of the oldest venture capital firms.","A chevron icon looks like a mountain peak.","The name comes from Mount Greylock, the highest point in Massachusetts."),
("lightspeed","Lightspeed","https://lsvp.com/","Lightspeed Venture Partners was founded in 2000.","An orange L-shaped mark looks like a corner or a step.","The serif wordmark balances a fast name with a traditional feel."),
("index-ventures","Index Ventures","https://www.indexventures.com/","Index Ventures was founded in Geneva in 1996 and now invests from London and San Francisco.","Red stacked lines look like an index or a list.","The tiny wordmark under the mark keeps the symbol in charge."),
("general-catalyst","General Catalyst","https://www.generalcatalyst.com/","General Catalyst was founded in Cambridge, Massachusetts, in 2000.","Tall, condensed capitals with special letter shapes feel engineered.","The custom lettering looks more like a tech brand than a finance firm."),
("y-combinator","Y Combinator","https://www.ycombinator.com/","Paul Graham, Jessica Livingston, Robert Morris and Trevor Blackwell founded Y Combinator in 2005.","A white Y in an orange square is one of the most recognisable startup symbols.","The name comes from a function in computer science, a nod to its programmer founders."),
("first-round-capital","First Round Capital","https://firstround.com/","Josh Kopelman founded First Round Capital in Philadelphia in 2004.","A giant number 1 is the whole logo.","Tiny vertical text inside the 1 spells out the name."),
("founders-fund","Founders Fund","https://foundersfund.com/","Peter Thiel, Ken Howery and Luke Nosek founded Founders Fund in San Francisco in 2005.","A small striped flag sits next to spaced capitals.","The colourful stripes add a playful touch to a very confident firm."),
("union-square-ventures","Union Square Ventures","https://www.usv.com/","Fred Wilson and Brad Burnham founded Union Square Ventures in New York in 2003.","USV in white on a green square looks like an app icon.","The firm is named after the Manhattan square near its office."),
("initialized-capital","Initialized Capital","https://initialized.com/","Garry Tan and Alexis Ohanian founded Initialized Capital in 2011.","Lowercase type with round brackets looks like a line of code.","The name is a programming term, which suits a firm founded by engineers."),
("techstars","Techstars","https://www.techstars.com/","Techstars was founded in Boulder, Colorado, in 2006.","Lowercase letters end in a green underscore, like a blinking cursor.","The cursor detail turns a simple wordmark into a tech reference."),
("500-global","500 Global","https://500.co/","Dave McClure and Christine Tsai founded the firm as 500 Startups in 2010, and it was renamed 500 Global in 2021.","A heavy, slanted 500 is the whole logo.","Dropping \"Startups\" from the name let the number stand on its own."),
("pear-vc","Pear VC","https://pear.vc/","Pejman Nozad and Mar Hershenson founded Pear VC in 2013.","A green pear sits next to a heavy wordmark.","The name blends the founders' first names into a simple fruit."),
("sv-angel","SV Angel","https://svangel.com/","Ron Conway founded SV Angel, one of Silicon Valley's best-known seed investors.","A gold halo floats above the name, a picture of the word angel.","Rounded, friendly letters make the firm feel approachable."),
("tiger-global","Tiger Global","https://www.tigerglobal.com/","Chase Coleman founded Tiger Global in New York in 2001.","Two words in contrasting colours split tiger and global.","The serif capitals feel more like a hedge fund than a startup brand."),
("coatue","Coatue","https://www.coatue.com/","Philippe Laffont founded Coatue in New York in 1999.","Thin, spaced capitals keep the logo very quiet.","The unusual name is easy to remember even without a symbol."),
("ivp","IVP","https://www.ivp.com/","IVP was founded in 1980 as Institutional Venture Partners.","Bold blue lowercase letters feel friendly and modern.","The dot over the i is a full circle, like a period."),
("bessemer-venture-partners","Bessemer Venture Partners","https://www.bvp.com/","Bessemer traces its roots to 1911 and the fortune of Henry Phipps, who made his money in steel.","Bessemer in bold over Venture Partners in light type splits the name clearly.","The name comes from the Bessemer steel-making process."),
("battery-ventures","Battery Ventures","https://www.battery.com/","Battery Ventures was founded in Boston in 1983.","A blue triangle in the corner of the y looks like a battery terminal.","Rounded letters feel friendly and energetic."),
("thrive-capital","Thrive Capital","https://thrivecap.com/","Joshua Kushner founded Thrive Capital in New York in 2009.","A red chevron points forward like an arrow.","Condensed capitals give the long name a compact, confident shape."),
("lux-capital","Lux Capital","https://www.luxcapital.com/","Josh Wolfe and Peter Hébert founded Lux Capital in New York in 2000.","An angular mark combines the letters L and U.","Lux means light in Latin, a hint at the firm's focus on science."),
("nea","NEA","https://www.nea.com/","NEA was founded in Baltimore in 1977 as New Enterprise Associates.","Huge, heavy serif capitals feel bold and established.","Navy and white make the initials feel like a classic institution."),
("ribbit-capital","Ribbit Capital","https://ribbitcap.com/","Micky Malka founded Ribbit Capital in Palo Alto in 2012 to invest in fintech.","A bold Ribbit next to a light Capital splits the name in two.","The name is the sound a frog makes, an unusual choice for an investor."),
("atomico","Atomico","https://atomico.com/","Niklas Zennström, a co-founder of Skype, founded Atomico in London in 2006.","Rounded lowercase letters feel modern and friendly.","A small teal circle after the name looks like an atom."),
("balderton-capital","Balderton Capital","https://www.balderton.com/","Balderton started as Benchmark Capital Europe in 2000 and became independent in 2007.","A simple serif name ends with an orange full stop.","The dot is the only colour, which makes it memorable."),
("northzone","Northzone","https://northzone.com/","Northzone was founded in 1996 in Scandinavia and was an early investor in Spotify.","Serif capitals feel solid and Nordic.","The name points to the firm's northern European roots."),
("creandum","Creandum","https://www.creandum.com/","Creandum was founded in Stockholm in 2003 and was also an early Spotify investor.","Very widely spaced capitals feel clean and modern.","The name comes from Latin and means something like \"to be created\"."),
("seedcamp","Seedcamp","https://seedcamp.com/","Seedcamp was founded in London in 2007 and is one of Europe's best-known seed funds.","Thin capitals in dark green feel calm and confident.","The name is a simple mix of seed and camp."),
("point-nine","Point Nine","https://www.pointnine.com/","Point Nine was founded in Berlin in 2011 and focuses on SaaS and marketplaces.","A heavy number 9 with a dot is the whole logo.","The mark is a literal picture of the name, point nine."),
("hongshan","HongShan","https://www.hongshan.com/","HongShan was formerly Sequoia Capital China and became an independent firm in 2023.","Small capitals in English sit over the Chinese name.","A green zigzag mark looks like a tree or a mountain path."),
("softbank-vision-fund","SoftBank Vision Fund","https://visionfund.com/","Masayoshi Son launched the SoftBank Vision Fund in 2017 with around $100 billion.","Light, simple type keeps the giant fund's name calm.","The lack of a symbol puts the SoftBank name in front."),
("peak-xv-partners","Peak XV Partners","https://www.peakxv.com/","Peak XV was formerly Sequoia Capital India and Southeast Asia and took its new name in 2023.","Heavy Peak and a purple XV make a bold, modern logo.","Peak XV was the early survey name for Mount Everest."),
("khosla-ventures","Khosla Ventures","https://www.khoslaventures.com/","Vinod Khosla, a co-founder of Sun Microsystems, founded Khosla Ventures in 2004.","Simple lowercase letters feel modest and modern.","The founder's name is the brand, with no symbol needed."),
("spark-capital","Spark Capital","https://www.sparkcapital.com/","Spark Capital was founded in Boston in 2005.","A heavy, rounded S is the whole mark.","The simple letter works as an icon on any background."),
("crv","CRV","https://www.crv.com/","CRV was founded in 1970 as Charles River Ventures in Boston.","Three heavy geometric capitals feel strong and modern.","Shortening the name to initials made an old firm feel new."),
("felicis","Felicis","https://www.felicis.com/","Aydin Senkut founded Felicis in 2006.","An orange four-leaf clover sits next to the name.","Felicis comes from Latin and means lucky."),
("redpoint","Redpoint","https://www.redpoint.com/","Redpoint was founded in Menlo Park in 1999.","A red peak icon sits next to the name.","The full stop after the name adds confidence."),
("gv","GV","https://www.gv.com/","GV launched in 2009 as Google Ventures, the venture arm of Google, now Alphabet.","A G and a slash form a very short mark.","Dropping the Google name gave the fund its own identity."),
("8vc","8VC","https://www.8vc.com/","Joe Lonsdale founded 8VC in 2015.","Very thin, light letters make the short name feel technical.","The number 8 is easy to remember and works as a symbol."),
("mayfield","Mayfield","https://www.mayfield.com/","Mayfield was founded in Menlo Park in 1969 and is one of the oldest venture firms.","A flowing script makes the firm feel personal.","\"People First\" next to the name sums up its message."),
("emergence-capital","Emergence Capital","https://www.emcap.com/","Emergence Capital was founded in 2003 and focuses on enterprise software.","A blocky E mark looks like a building block.","Spaced capitals keep the long name clean."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 45
